import{_ as t,o as r,c as a,a0 as d}from"./chunks/framework.BdKrsJIB.js";const u=JSON.parse('{"title":"Crates","description":"","frontmatter":{},"headers":[],"relativePath":"reference/crates.md","filePath":"reference/crates.md"}'),s={name:"reference/crates.md"};function o(i,e,c,n,l,p){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="crates" tabindex="-1">Crates <a class="header-anchor" href="#crates" aria-label="Permalink to &quot;Crates&quot;">​</a></h1><p>Rust workspace, ports-and-adapters — the same anatomy as tamias/bupha/peregrin. <code>tarsi-core</code> is pure domain (no I/O); <code>tarsi-serve</code> is the composition root and the only shipped binary.</p><table tabindex="0"><thead><tr><th>crate</th><th>layer</th><th>purpose</th></tr></thead><tbody><tr><td><code>tarsi-core</code></td><td>domain</td><td>Pure release-domain model — plans, units, semver bumps, commit classification, changelog. No I/O.</td></tr><tr><td><code>tarsi-publish</code></td><td>port</td><td>Publish port — per-forge Publisher impls (crates.io, GitHub Releases, dry-run).</td></tr><tr><td><code>tarsi-config</code></td><td>adapter</td><td>tarsi.toml/tarsi.yml loading — scarab-config file discovery over tarsi_core::Config, plus type:tarsi release-profile resolution.</td></tr><tr><td><code>tarsi-manifest</code></td><td>adapter</td><td>Cargo manifest scanning — workspace members → tarsi_core::ReleaseUnitSpec, version reads/writes.</td></tr><tr><td><code>tarsi-publish-crates</code></td><td>adapter</td><td>crates.io Publisher — dep-ordered cargo publish with 429 retry (release.sh semantics).</td></tr><tr><td><code>tarsi-publish-dryrun</code></td><td>adapter</td><td>Dry-run Publisher — validates and reports every target without remote writes.</td></tr><tr><td><code>tarsi-publish-ghreleases</code></td><td>adapter</td><td>GitHub Releases publisher — release create + notes + asset upload via ureq (blocking, bupha-github convention).</td></tr><tr><td><code>tarsi-serve</code></td><td>engine</td><td>tarsi service surface — ndjson ops (plan/changelog/notes/check/schema + granular bump/tag/publish + release) over tarsi-core + lasius-vcs.</td></tr><tr><td><code>tarsi-driver</code></td><td>driver</td><td>tamias-driver-tarsi — tamias content driver for type:tarsi release-profile packs</td></tr><tr><td><code>tarsi-testkit</code></td><td>testkit</td><td>Conformance fixtures + golden corpus for tarsi ports/impls.</td></tr><tr><td><code>tarsi-xtask</code></td><td>tooling</td><td>Repo chores: check / test / coverage / install / package / smoke / site</td></tr></tbody></table><h2 id="key-external-deps" tabindex="-1">Key external deps <a class="header-anchor" href="#key-external-deps" aria-label="Permalink to &quot;Key external deps&quot;">​</a></h2><ul><li><code>lasius-vcs</code> + <code>lasius-vcs-git</code> — all git history/tag/push (P-019); <code>tarsi-core</code> sees only <code>Commit</code> values.</li><li><code>scarab-config</code> + <code>scarab-config-file</code> — config discovery and layering (P-017); no <code>tarsi-config-*</code> format crates.</li><li><code>hypha-serve-cli</code> — the shared one-shot argv→params shim.</li><li><code>semver</code>, <code>toml_edit</code>, <code>serde</code>/<code>serde_json</code> — versions, manifest mutation, the wire.</li></ul><p>API docs: <code>bun run docs:api</code> renders <code>cargo doc</code> into <code>public/api/</code> (linked from the built site under <code>/tarsi/api/</code>).</p>',6)])])}const m=t(s,[["render",o]]);export{u as __pageData,m as default};
